'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
function model(){const c={window:{}};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'visual-system.js'),'utf8'),c);return c.window.PhoenixVisualModel;}
test('existing action labels and routes select the approved button symbols',()=>{const m=model();for(const [input,purpose]of [[{text:'←',label:'Previous objective card'},'previous'],[{text:'Next →'},'next'],[{text:'Continue walkthrough'},'continue'],[{text:'Start walkthrough'},'continue'],[{text:'Return to Search'},'return'],[{text:'Back to navigation'},'return'],[{text:'Map'},'map'],[{text:'Locate',href:'#whiteorchard-map/pin/forge'},'map'],[{text:'Record / review choice'},'plain']])assert.equal(m.classifyAction(input),purpose);});
test('category lighting uses established region, progress and reference colors',()=>{const m=model();assert.equal(m.categoryFor({closest:s=>s.includes('.main-region-selector')}),'#91b47c');assert.equal(m.categoryFor({closest:s=>s==='#progress'}),'#c79e63');assert.equal(m.categoryFor({closest:s=>s.includes('.diagram-view')}),'#b3cbd0');assert.equal(m.categoryFor({closest:()=>false}),'#8bb9bd');});
test('eye awakening has one bounded timer and settles after interaction',()=>{const m=model(),classes=new Set(),timers=new Map();let serial=0;const pointer={classList:{add:x=>classes.add(x),remove:x=>classes.delete(x)}},pulse=m.createPulse(pointer,{setTimer(fn,ms){assert.equal(ms,850);const id=++serial;timers.set(id,fn);return id;},clearTimer:id=>timers.delete(id)});pulse.wake();pulse.wake();assert.equal(timers.size,1);assert.equal(classes.has('is-awake'),true);[...timers.values()][0]();assert.equal(classes.has('is-awake'),false);});
test('quiet clears pending effects and never changes pointer or control identity',()=>{const m=model(),classes=new Set(),timers=new Map();const pointer={id:'original',classList:{add:x=>classes.add(x),remove:x=>classes.delete(x)}},pulse=m.createPulse(pointer,{setTimer(fn){timers.set(1,fn);return 1;},clearTimer:id=>timers.delete(id)});pulse.wake();pulse.quiet();assert.equal(timers.size,0);assert.equal(classes.size,0);assert.equal(pointer.id,'original');});
test('production pointer and button assets exist and fit the static delivery budget',()=>{for(const f of ['wolf-pointer.webp','iron-button-frame.webp','ink-rule.svg','icon-continue.svg','icon-map.svg','icon-return.svg','icon-previous.svg','icon-next.svg']){const size=fs.statSync(path.join(__dirname,'visual-art',f)).size;assert.ok(size>100);assert.ok(size<120000);}});

test('nested primary labels keep word boundaries when choosing the journal symbol',()=>{const m=model(),text=m.actionText({childNodes:[{textContent:'Continue walkthrough'},{textContent:'Search the shields'}]});assert.equal(text,'Continue walkthrough Search the shields');assert.equal(m.classifyAction({text}),'continue');});
